  return (
    <div className="grid h-full w-full grid-cols-3 grid-rows-2 gap-2 bg-[#FAF9F6] p-4">
      {items.map((it, i) => {
        const isOpen = open === i;
        return (
          <motion.button
            layout
            key={it.t}
            onClick={() => setOpen(i)}
            aria-expanded={isOpen}
            transition={{ type: "spring", stiffness: 350, damping: 32 }}
