function Word({ w, i, last, mx, my }) {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const away = useTransform([mx, my], ([x, y]) => {
    if (reduce || !ref.current || x < 0) return 0;
    const b = ref.current.getBoundingClientRect();
    const dx = b.left + b.width / 2 - x, dy = b.top + b.height / 2 - y;
    const dist = Math.hypot(dx, dy);
    return dist < 160 ? (dx / Math.max(dist, 1)) * (160 - dist) * 0.12 : 0;
  });
  const lean = useSpring(away, { stiffness: 300, damping: 18 });
  const skew = useTransform(lean, (v) => -v * 0.6);
  return (
    <motion.div ref={ref} initial={reduce ? false : { y: -40, rotate: -8, opacity: 0 }} animate={{ y: 0, rotate: 0, opacity: 1 }} transition={{ type: "spring", stiffness: 350, damping: 14, delay: i * 0.09 }} style={{ x: lean, skewX: skew, color: last ? "#D9534F" : undefined }}
      className={"w-fit text-[3.1rem] leading-[0.95] tracking-[-0.04em] " + (last ? "font-serif font-normal italic" : "font-black")}>{w}</motion.div>
  );
}
