function cable(n) {
  const cx = 330, cy = 330, x = n[2], y = n[3];
  const mx = (cx + x) / 2, my = (cy + y) / 2;
  const dx = y - cy, dy = cx - x;
  return "M" + cx + " " + cy + " C" + (mx + dx * 0.35) + " " + (my + dy * 0.35) + " " + (mx - dx * 0.2) + " " + (my - dy * 0.2) + " " + x + " " + y;
}

function Emblem() {
  const oct = (r) => { const p = []; for (let i = 0; i < 8; i++) { const a = Math.PI / 8 + (i * Math.PI) / 4; p.push((330 + r * Math.cos(a)).toFixed(1) + "," + (330 + r * Math.sin(a)).toFixed(1)); } return p.join(" "); };
  return (
    <g>
      <polygon points={oct(104)} fill={BONE} stroke={BG} strokeWidth="4" />
      <polygon points={oct(88)} fill="none" stroke={BG} strokeWidth="2" />
      <g stroke={BG} strokeWidth="7" fill="none" strokeLinecap="square">
        <path d="M262 300 H300 L318 282 H360" /><path d="M262 352 H292 L312 372 H396" /><path d="M354 252 V292 L372 310 V352" /><path d="M300 400 V372" />
      </g>
      <circle cx="330" cy="330" r="22" fill={BG} />
      <circle cx="330" cy="330" r="8" fill={SIG} />
      {[[262, 300], [262, 352], [354, 252], [300, 400], [396, 372], [360, 282]].map(([x, y], i) => <circle key={i} cx={x} cy={y} r="7" fill={BONE} stroke={BG} strokeWidth="4" />)}
    </g>
  );
}

