function ShotClock({ reset }) {
  const [t, setT] = useState(240);
  useEffect(() => { setT(240); }, [reset]);
  useEffect(() => {
    const id = setInterval(() => setT((v) => (v <= -10 ? 240 : v - 1)), 100);
    return () => clearInterval(id);
  }, []);
  const out = t <= 0;
  const show = t > 50 ? Math.ceil(t / 10) : Math.max(0, t / 10).toFixed(1);
  return (
    <motion.div animate={{ backgroundColor: out ? RED : INK }} transition={{ duration: 0.1 }} className="flex w-[200px] flex-col items-center rounded-[10px] border-4 border-[#151412] px-4 pb-3 pt-2">
      <span className="text-[11px] font-bold tracking-[0.2em] text-[#FBFAF5]/70" style={MONO}>SHOT CLOCK</span>
      <span className="text-[4.4rem] leading-[1.05] text-[#E8321E]" style={{ ...DELA, ...NUM, color: out ? INK : RED }}>{show}</span>
    </motion.div>
  );
}

function Hero() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const bx = useMotionValue(HOME), by = useMotionValue(560), spin = useMotionValue(0);
  const s = useRef({ mode: "idle", vx: 0, vy: 0, hist: [], since: 0 });
  const [score, setScore] = useState(0);
  const [swish, setSwish] = useState(0);
  const tx = useTransform(bx, (v) => v - R), ty = useTransform(by, (v) => v - R);
  const shadowX = useTransform(bx, (v) => v - 40);
  const shadowS = useTransform(by, (v) => 0.4 + (v / FLOOR) * 0.6);
  useAnimationFrame((time, dt) => {
    const st = s.current;
    const d = Math.min(dt, 32) / 1000;
    if (st.mode === "idle") {
      bx.set(bx.get() + (HOME - bx.get()) * 0.08);
      by.set(reduce ? FLOOR - R : FLOOR - R - Math.abs(Math.sin(time / 260)) * 190);
      spin.set(spin.get() + 1.2);
    } else if (st.mode === "fly") {
      st.vy += 2600 * d;
      let x = bx.get() + st.vx * d, y = by.get() + st.vy * d;
      const py = by.get();
      if (py < RIM.y && y >= RIM.y && x > RIM.x1 + 6 && x < RIM.x2 - 6 && st.vy > 0) {
        setScore((v) => v + 2);
        setSwish((v) => v + 1);
        st.vx *= 0.2;
      }
      if (x > 1080 && x < 1130 && y > 190 && y < 350 && st.vx > 0) { st.vx = -st.vx * 0.5; x = 1080; }
      if (x < R) { x = R; st.vx = -st.vx * 0.6; }
      if (x > 1280 - R) { x = 1280 - R; st.vx = -st.vx * 0.6; }
      if (y > FLOOR - R) { y = FLOOR - R; st.vy = -st.vy * 0.55; st.vx *= 0.85; }
      bx.set(x); by.set(y);
      spin.set(spin.get() + st.vx * d * 1.4);
      if (time - st.since > 2600) st.mode = "idle";
    }
  });
  const local = (e) => {
    const b = ref.current.getBoundingClientRect();
    const k = b.width / ref.current.offsetWidth;
    return [(e.clientX - b.left) / k, (e.clientY - b.top) / k];
  };
  const down = (e) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    s.current.mode = "drag";
    s.current.hist = [[...local(e), performance.now()]];
  };
  const move = (e) => {
    if (s.current.mode !== "drag") return;
    const p = local(e);
    bx.set(p[0]); by.set(Math.min(p[1], FLOOR - R));
    s.current.hist = s.current.hist.concat([[p[0], p[1], performance.now()]]).slice(-5);
  };
  const up = () => {
    const st = s.current;
    if (st.mode !== "drag") return;
    const h = st.hist, a = h[0], b = h[h.length - 1];
    const dt = Math.max(16, b[2] - a[2]);
    st.vx = Math.max(-2600, Math.min(2600, ((b[0] - a[0]) / dt) * 1000));
    st.vy = Math.max(-2600, Math.min(2600, ((b[1] - a[1]) / dt) * 1000));
    st.mode = "fly";
    st.since = performance.now();
  };
  const shoot = () => {
    bx.set(HOME); by.set(560);
    s.current = { ...s.current, mode: "fly", vx: 424, vy: -1265, since: performance.now() };
  };
  return (
    <section ref={ref} className="relative h-[760px] select-none overflow-hidden" style={{ background: CONC }}>
      <div aria-hidden="true" className="absolute inset-0 opacity-50" style={{ backgroundImage: "radial-gradient(#9E998E 1px, transparent 1.4px), radial-gradient(#E2DED6 1px, transparent 1.4px)", backgroundSize: "9px 9px, 13px 13px", backgroundPosition: "0 0, 4px 6px" }} />
      <svg aria-hidden="true" className="absolute inset-0 h-full w-full" viewBox="0 0 1280 760">
        <path d="M780 760 L900 300 L1150 300 L1270 760 Z" fill={RED} />
        <g fill="none" stroke={CHALK} strokeWidth="7">
          <path d="M780 760 L900 300 L1150 300 L1270 760" />
          <ellipse cx="1025" cy="300" rx="125" ry="42" />
          <path d="M560 760 Q700 380 1025 360 Q1350 380 1490 760" />
        </g>
      </svg>
      <div aria-hidden="true" className="absolute left-[1015px] top-[340px] h-[340px] w-[18px] bg-[#151412]" />
      <div aria-hidden="true" className="absolute left-[930px] top-[190px] h-[160px] w-[200px] rounded-[6px] border-[6px] border-[#151412] bg-[#FBFAF5]/90">
        <div className="absolute bottom-3 left-1/2 h-[60px] w-[74px] -translate-x-1/2 border-[5px] border-[#E8321E]" />
      </div>
      <div className="absolute left-12 top-14 z-10">
        <p className="text-[13px] font-bold tracking-[0.2em] text-[#151412]" style={MONO}>DROP 07. FRIDAY 18:00. 400 PIECES</p>
        <h1 className="mt-4 text-[8.6rem] uppercase leading-[0.88] text-[#151412]" style={DELA}>No look<br /><span className="text-[#E8321E]">pack</span></h1>
        <p className="mt-6 max-w-[380px] text-[15px] leading-relaxed text-[#151412]" style={MONO}>Heavyweight mesh, reversible jerseys and a high-top that grips cracked asphalt. Cut for pickup, not for the shelf.</p>
        <div className="mt-8 flex items-center gap-4">
          <a href="#" className="flex items-center gap-3 rounded-full bg-[#151412] px-7 py-4 text-lg uppercase text-[#FBFAF5]" style={DELA}>Get on the list<ArrowUpRight size={20} /></a>
          <button onClick={shoot} className="rounded-full border-[3px] border-[#151412] px-6 py-[14px] text-sm font-bold uppercase tracking-[0.1em] text-[#151412] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4" style={MONO}>Take the shot</button>
        </div>
      </div>
      <div className="absolute left-[930px] top-6 z-10"><ShotClock reset={swish} /></div>
      <div className="absolute bottom-24 left-[540px] z-10 text-[#151412]" style={MONO}>
        <span className="text-[12px] font-bold tracking-[0.2em]">BUCKETS</span>
        <motion.p key={score} initial={{ scale: 1.5, color: RED }} animate={{ scale: 1, color: INK }} transition={{ type: "spring", stiffness: 300, damping: 14 }} className="origin-left text-[4rem] leading-none" style={{ ...DELA, ...NUM }}>{score}</motion.p>
        <span className="text-[12px]">Drag the ball, throw it at the rim</span>
      </div>
      <motion.div aria-hidden="true" className="absolute left-0 top-[700px] h-5 w-20 rounded-full bg-[#151412]/30" style={{ x: shadowX, scaleX: shadowS }} />
      <motion.div onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} className="absolute left-0 top-0 z-20 cursor-grab touch-none active:cursor-grabbing" style={{ x: tx, y: ty, width: R * 2, height: R * 2 }} role="img" aria-label="Basketball, drag and throw">
        <motion.div className="h-full w-full" style={{ rotate: spin }}><Ball /></motion.div>
      </motion.div>
      <div aria-hidden="true" className="absolute z-30" style={{ left: RIM.x1 - 6, top: RIM.y - 6 }}>
        <div className="h-[14px] w-[112px] rounded-full border-[5px] border-[#E8321E] bg-transparent" />
        <svg width="112" height="70" viewBox="0 0 112 70" className="-mt-1"><path d="M4 2 L22 66 M30 2 L38 66 M56 2 L56 66 M82 2 L74 66 M108 2 L90 66 M10 22 H102 M16 44 H96 M22 66 H90" fill="none" stroke={CHALK} strokeWidth="3" /></svg>
      </div>
      <AnimatePresence>
        {swish > 0 && (
          <motion.div key={swish} initial={{ opacity: 0, scale: 0.6, rotate: -12 }} animate={{ opacity: [0, 1, 1, 0], scale: [0.6, 1.1, 1, 1.05], rotate: -8 }} transition={{ duration: 1.4, times: [0, 0.2, 0.75, 1] }} className="pointer-events-none absolute left-[600px] top-[300px] z-30 bg-[#151412] px-6 py-2 text-6xl uppercase text-[#E8321E]" style={DELA}>Swish +2</motion.div>
        )}
      </AnimatePresence>
      <Tape />
    </section>
  );
}

