const UNB = { fontFamily: "'Unbounded', sans-serif" };
const MONO = { fontFamily: "'Geist Mono', monospace" };
const SANS = { fontFamily: "'Geist', sans-serif" };
const NUM = { fontVariantNumeric: "tabular-nums" };
const PAPER = "#F4F4F0", INK = "#0B0B0C";
const LAP_MS = 6400, LAP_S = 91.412;
const TRACK = "M70 320 H330 C380 320 392 282 410 240 L460 122 C476 82 442 50 400 60 L250 100 C210 110 200 150 230 170 L300 215 C330 235 312 262 280 256 L120 230 C70 222 40 250 45 285 C48 310 55 320 70 320 Z";
const TYRES = [
  { k: "Soft", c: "#E8202A", on: "#FFFFFF", lap: "1:31.4", deg: "0.11 s/lap", stint: 14, grip: 96 },
  { k: "Medium", c: "#F5C400", on: INK, lap: "1:31.9", deg: "0.06 s/lap", stint: 26, grip: 84 },
  { k: "Hard", c: "#A3A39C", on: INK, lap: "1:32.5", deg: "0.03 s/lap", stint: 38, grip: 71 },
  { k: "Inter", c: "#1FA34A", on: "#FFFFFF", lap: "1:41.2", deg: "0.08 s/lap", stint: 22, grip: 58 },
  { k: "Wet", c: "#1E6BE0", on: "#FFFFFF", lap: "1:47.8", deg: "0.05 s/lap", stint: 30, grip: 44 },
];
const ROUNDS = [["R15", "Monza", "07 SEP", "P4"], ["R16", "Baku", "21 SEP", "P2"], ["R17", "Marina Bay", "05 OCT", "P6"], ["R18", "Austin", "19 OCT", "Next"], ["R19", "Mexico City", "26 OCT", ""], ["R20", "Interlagos", "09 NOV", ""]];
const speedAt = (p) => 118 + 214 * Math.pow(Math.abs(Math.sin(p * Math.PI * 3 + 0.4)), 0.7);
const fmt = (s) => { const m = Math.floor(s / 60), r = s - m * 60; return m + ":" + (r < 10 ? "0" : "") + r.toFixed(3); };

function Streaks() {
  const reduce = useReducedMotion();
  if (reduce) return null;
  return Array.from({ length: 20 }).map((_, i) => (
    <motion.div key={i} aria-hidden="true" className="pointer-events-none absolute left-0 rounded-full" style={{ top: 40 + ((i * 137) % 640), width: 120 + ((i * 53) % 260), height: i % 3 ? 3 : 6, background: i % 3 ? INK : "var(--acc)", opacity: i % 3 ? 0.1 + (i % 4) * 0.05 : 0.75 }} initial={{ x: 1400 }} animate={{ x: -500 }} transition={{ duration: 0.55 + (i % 5) * 0.18, repeat: Infinity, ease: "linear", delay: (i * 0.137) % 1.2 }} />
  ));
}

function TrackCard({ phase, lap, sector }) {
  const pathRef = useRef(null);
  const cx = useMotionValue(70), cy = useMotionValue(320);
  useMotionValueEvent(phase, "change", (p) => {
    const el = pathRef.current;
    if (!el) return;
    const pt = el.getPointAtLength(p * el.getTotalLength());
    cx.set(pt.x); cy.set(pt.y);
  });
  const time = useTransform(phase, (p) => fmt(p * LAP_S));
  const sc = ["#8B2CF5", "#16A34A", "#F5C400"];
  return (
    <div className="relative w-[500px] rounded-[20px] bg-[#0B0B0C] p-6 text-[#F4F4F0]" style={MONO}>
      <div className="flex items-center justify-between text-[12px] tracking-[0.14em] text-[#F4F4F0]/60"><span>AUSTIN. 5.51 KM, 20 TURNS</span><span style={NUM}>LAP {lap}/56</span></div>
      <svg viewBox="0 0 520 380" className="mt-2 h-[300px] w-full" aria-hidden="true">
        <path d={TRACK} fill="none" stroke="#2A2A2D" strokeWidth="22" strokeLinejoin="round" />
        <path ref={pathRef} d={TRACK} fill="none" stroke="#F4F4F0" strokeWidth="3" strokeLinejoin="round" />
        <path d="M70 306 V334" stroke="var(--acc)" strokeWidth="6" />
        <motion.circle r="11" fill="var(--acc)" stroke="#0B0B0C" strokeWidth="3" style={{ cx, cy }} />
      </svg>
      <div className="flex items-end justify-between">
        <motion.span className="text-[3rem] leading-none" style={{ ...UNB, ...NUM, fontWeight: 700 }}>{time}</motion.span>
        <div className="flex gap-2">
          {[0, 1, 2].map((i) => <span key={i} className="flex h-9 w-14 items-center justify-center rounded-[6px] text-[12px] font-medium transition-colors duration-200" style={{ background: sector > i ? sc[i] : "#2A2A2D", color: sector > i && i === 2 ? INK : "#F4F4F0" }}>S{i + 1}</span>)}
        </div>
      </div>
    </div>
  );
}

