function Telemetry({ phase }) {
  const pts = useMemo(() => Array.from({ length: 241 }).map((_, i) => (i * 10.667).toFixed(1) + "," + (130 - (speedAt((i % 120) / 120) - 100) * 0.48).toFixed(1)).join(" "), []);
  const x = useTransform(phase, (p) => -p * 1280);
  const spd = useTransform(phase, (p) => Math.round(speedAt(p)));
  const gear = useTransform(phase, (p) => Math.max(2, Math.min(8, Math.round((speedAt(p) - 80) / 34))));
  const thr = useTransform(phase, (p) => Math.min(1, Math.max(0.05, (speedAt(p) - 120) / 200 + 0.15 * Math.cos(p * 40))));
  const brk = useTransform(phase, (p) => Math.max(0, -Math.cos(p * Math.PI * 6 + 0.8) - 0.55) * 2.2);
  return (
    <section className="grid grid-cols-[280px_1fr] bg-[#0B0B0C] text-[#F4F4F0]" style={MONO}>
      <div className="flex flex-col justify-between border-r border-[#F4F4F0]/15 p-8">
        <div>
          <p className="text-[12px] tracking-[0.16em] text-[#F4F4F0]/55">SPEED KM/H</p>
          <motion.p className="text-[5rem] leading-none" style={{ ...UNB, ...NUM, fontWeight: 700 }}>{spd}</motion.p>
        </div>
        <div className="mt-6 flex items-end gap-6">
          <div><p className="text-[12px] tracking-[0.16em] text-[#F4F4F0]/55">GEAR</p><motion.p className="text-[3rem] leading-none" style={{ ...UNB, fontWeight: 700 }}>{gear}</motion.p></div>
          <div className="flex h-24 gap-3">
            {[["THR", thr, "#16A34A"], ["BRK", brk, "#E8202A"]].map(([l, v, c]) => (
              <div key={l} className="flex flex-col items-center gap-1"><div className="relative h-20 w-5 overflow-hidden rounded-[3px] bg-[#2A2A2D]"><motion.div className="absolute inset-x-0 bottom-0 h-full origin-bottom" style={{ scaleY: v, background: c }} /></div><span className="text-[10px]">{l}</span></div>
            ))}
          </div>
        </div>
      </div>
      <div className="relative h-[260px] overflow-hidden">
        <div className="absolute inset-0" style={{ backgroundImage: "linear-gradient(#F4F4F0 1px, transparent 1px)", backgroundSize: "100% 52px", opacity: 0.07 }} />
        <motion.svg width="2560" height="260" viewBox="0 0 2560 260" className="absolute left-0 top-6" style={{ x }} aria-hidden="true">
          <polyline points={pts} fill="none" stroke="var(--acc)" strokeWidth="3" strokeLinejoin="round" />
        </motion.svg>
        <div className="absolute inset-y-0 left-[40%] w-[2px] bg-[#F4F4F0]/50" />
        <p className="absolute bottom-4 right-6 text-[12px] tracking-[0.16em] text-[#F4F4F0]/55">CAR 27. SPEED TRACE, LIVE</p>
      </div>
    </section>
  );
}

