function Demo() {
  const reduce = useReducedMotion();
  const phase = useMotionValue(0.08);
  const [lap, setLap] = useState(34);
  const [sector, setSector] = useState(0);
  const [pick, setPick] = useState(0);
  const auto = useRef(true);
  const prev = useRef(0);
  useAnimationFrame((t) => {
    if (reduce) return;
    const p = (t % LAP_MS) / LAP_MS;
    phase.set(p);
    if (p < prev.current) setLap((l) => (l >= 56 ? 1 : l + 1));
    const s = p > 0.66 ? 2 : p > 0.33 ? 1 : 0;
    const ps = prev.current > 0.66 ? 2 : prev.current > 0.33 ? 1 : 0;
    if (s !== ps || p < prev.current) setSector(p < prev.current ? 3 : s);
    prev.current = p;
  });
  useEffect(() => {
    if (reduce) return;
    const id = setInterval(() => { if (auto.current) setPick((v) => (v + 1) % TYRES.length); }, 3200);
    return () => clearInterval(id);
  }, [reduce]);
  const t = TYRES[pick];
  return (
    <div className="w-full selection:bg-[#0B0B0C] selection:text-[#F4F4F0]" style={{ background: PAPER, "--acc": t.c, "--on": t.on, ...SANS }}>
      <nav className="flex h-[70px] items-center justify-between border-b-2 border-[#0B0B0C] px-12 text-[#0B0B0C]">
        <a href="#" className="flex items-center gap-3 text-2xl uppercase" style={{ ...UNB, fontWeight: 900 }}>
          <span className="flex gap-1" aria-hidden="true">{[0, 1, 2].map((i) => <span key={i} className="block h-6 w-2 skew-x-[-20deg] transition-colors duration-500" style={{ background: i === 2 ? "var(--acc)" : INK }} />)}</span>Ostro
        </a>
        <div className="flex gap-9 text-[15px] font-medium">{["Team", "Car", "Calendar", "Partners", "Store"].map((l) => <a key={l} href="#" className="hover:underline hover:underline-offset-4">{l}</a>)}</div>
        <a href="#" className="flex items-center gap-2 text-[13px] tracking-[0.12em]" style={MONO}><Play size={14} />WATCH ONBOARD</a>
      </nav>
      <Hero phase={phase} lap={lap} sector={sector} />
      <Telemetry phase={phase} />
      <Strategy pick={pick} setPick={setPick} auto={auto} />
      <Drivers />
      <Calendar />
      <footer className="overflow-hidden bg-[#0B0B0C] px-12 pb-10 pt-16 text-[#F4F4F0]">
        <p className="text-[10.5rem] uppercase leading-[0.85]" style={{ ...UNB, fontWeight: 900, transform: "skewX(-9deg)", transformOrigin: "left bottom" }}>Flat <span className="transition-colors duration-500" style={{ color: "var(--acc)" }}>out</span></p>
        <div className="mt-10 flex justify-between border-t border-[#F4F4F0]/20 pt-5 text-sm" style={MONO}><span>Ostro Racing, Via Nizza 210, Turin</span><span>press@ostroracing.team</span><span>Instagram / YouTube / X</span></div>
      </footer>
