function Flap({ ch, size = 1, delay = 0 }) {
  const [cur, setCur] = useState(" ");
  const reduce = useReducedMotion();
  useEffect(() => {
    if (reduce) { setCur(ch); return; }
    let i = ALPH.indexOf(cur), id;
    const target = ALPH.indexOf(ch);
    if (i === target) return;
    const start = setTimeout(() => {
      id = setInterval(() => {
        i = (i + 1) % ALPH.length;
        setCur(ALPH[i]);
        if (i === target) clearInterval(id);
      }, 38);
    }, delay);
    return () => { clearTimeout(start); clearInterval(id); };
  }, [ch]);
  const w = 74 * size, h = 104 * size;
  return (
    <span className="relative inline-flex items-center justify-center overflow-hidden rounded-[6px] bg-[#1E1A17]" style={{ width: w, height: h, perspective: 300 }}>
      <motion.span key={cur} initial={{ rotateX: reduce ? 0 : -70, opacity: 0.6 }} animate={{ rotateX: 0, opacity: 1 }} transition={{ duration: 0.05 }} className="text-[#FFC21A]" style={{ ...MONO, fontSize: 70 * size, fontWeight: 600, lineHeight: 1 }}>{cur}</motion.span>
      <span className="absolute inset-x-0 top-1/2 h-[2px] bg-[#F1E9DA]/25" />
    </span>
  );
}

