function Hero() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const roll = useMotionValue(0), pitch = useMotionValue(0);
  const sr = useSpring(roll, { stiffness: 60, damping: 14 }), sp = useSpring(pitch, { stiffness: 60, damping: 14 });
  const alt = useMotionValue(3200), ias = useMotionValue(112), hdg = useMotionValue(268);
  const last = useRef(-9999);
  useAnimationFrame((t) => {
    if (reduce) return;
    alt.set(3200 + ((t / 1000) * 38) % 1800);
    ias.set(112 + Math.sin(t / 900) * 2.4 + Math.sin(t / 310) * 0.6);
    hdg.set(268 + Math.sin(t / 2600) * 9);
    if (performance.now() - last.current > 1500) {
      roll.set(Math.sin(t / 1700) * 14 + Math.sin(t / 430) * 1.5);
      pitch.set(Math.sin(t / 2300) * 40 + Math.sin(t / 370) * 4);
    }
  });
  const move = (e) => {
    const b = ref.current.getBoundingClientRect();
    roll.set(((e.clientX - b.left) / b.width - 0.5) * 50);
    pitch.set(((e.clientY - b.top) / b.height - 0.5) * 220);
    last.current = performance.now();
  };
  const tf = useTransform([sr, sp], ([r, p]) => "translate(-50%, -50%) rotate(" + -r + "deg) translateY(" + p + "px)");
