function Radar() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  useEffect(() => {
    const cv = ref.current; const ctx = cv.getContext("2d");
    const S = 340, R = 160;
    cv.width = S * 2; cv.height = S * 2; ctx.scale(2, 2);
    const blips = [[0.6, 0.4], [2.1, 0.7], [3.3, 0.55], [4.4, 0.85], [5.4, 0.3], [1.3, 0.9]];
    let raf, a = 0;
    const draw = () => {
      ctx.clearRect(0, 0, S, S);
      ctx.save(); ctx.translate(S / 2, S / 2);
      ctx.strokeStyle = "rgba(215,255,59,0.18)"; ctx.lineWidth = 1;
      [0.25, 0.5, 0.75, 1].forEach((k) => { ctx.beginPath(); ctx.arc(0, 0, R * k, 0, Math.PI * 2); ctx.stroke(); });
      ctx.beginPath(); ctx.moveTo(-R, 0); ctx.lineTo(R, 0); ctx.moveTo(0, -R); ctx.lineTo(0, R); ctx.stroke();
      for (let i = 0; i < 40; i++) {
        ctx.beginPath(); ctx.moveTo(0, 0);
        ctx.arc(0, 0, R, a - (i + 1) * 0.022, a - i * 0.022);
        ctx.fillStyle = "rgba(215,255,59," + (0.32 * (1 - i / 40)) + ")"; ctx.fill();
      }
      blips.forEach(([ang, d], i) => {
        let diff = (a - ang) % (Math.PI * 2); if (diff < 0) diff += Math.PI * 2;
        const life = Math.max(0, 1 - diff / 3.2);
        const x = Math.cos(ang) * R * d, y = Math.sin(ang) * R * d;
        ctx.fillStyle = i === 2 ? "rgba(255,75,62," + (0.25 + life) + ")" : "rgba(236,234,226," + (0.15 + life) + ")";
        ctx.fillRect(x - 3, y - 3, 6, 6);
        if (life > 0.6) { ctx.strokeStyle = "rgba(215,255,59," + life + ")"; ctx.strokeRect(x - 8, y - 8, 16, 16); }
      });
      ctx.restore();
      a += 0.022; if (!reduce) raf = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf);
  }, [reduce]);
  return <canvas ref={ref} aria-hidden="true" style={{ width: 340, height: 340 }} />;
}

