function Embers() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  useEffect(() => {
    const cv = ref.current, ctx = cv.getContext("2d");
    const W = 1280, H = 760; cv.width = W; cv.height = H;
    const ps = Array.from({ length: 90 }, (_, i) => ({ x: (i * 137) % W, y: (i * 89) % H, v: 0.3 + (i % 7) * 0.12, r: 0.8 + (i % 4) * 0.7, p: i }));
    let raf, t = 0;
    const draw = () => {
      ctx.clearRect(0, 0, W, H); t += 0.016;
      ps.forEach((q) => {
        q.y -= q.v; q.x += Math.sin(t * 1.3 + q.p) * 0.4;
        if (q.y < -10) { q.y = H + 10; q.x = (q.x + 311) % W; }
        const a = 0.35 + 0.45 * Math.sin(t * 2 + q.p);
        ctx.fillStyle = "rgba(255," + (120 + (q.p % 5) * 20) + ",42," + Math.max(0.05, a) + ")";
        ctx.beginPath(); ctx.arc(q.x, q.y, q.r, 0, 6.29); ctx.fill();
      });
      if (!reduce) raf = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf);
  }, [reduce]);
  return <canvas ref={ref} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />;
}

