function Game() {
  const cv = useRef(null);
  const st = useRef({ x: 210, tx: 210, items: [], score: 0, idle: 3000, shake: 0, keys: {}, t: 0, best: 12 });
  const [hud, setHud] = useState({ score: 0, demo: true });
  const reduce = useReducedMotion();
  const toLocal = (e) => { const b = cv.current.getBoundingClientRect(); return ((e.clientX - b.left) / b.width) * 420; };
  useEffect(() => {
    const c = cv.current, ctx = c.getContext("2d");
    c.width = 840; c.height = 640; ctx.scale(2, 2);
    const S = st.current; S.items = [[70, 40, "d"], [180, 120, "d"], [300, 10, "d"], [250, 200, "c"], [120, 230, "d"], [360, 160, "d"]].map(([x, y, k]) => ({ x, y, v: 1.6, k, r: 0 })); let raf, last = 0, frame = 0;
    const dumpling = (x, y, r) => {
      ctx.fillStyle = "#FFF4E0"; ctx.beginPath(); ctx.ellipse(x, y, r, r * 0.78, 0, Math.PI, 0); ctx.lineTo(x + r, y + r * 0.3); ctx.lineTo(x - r, y + r * 0.3); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = "#E6C9A0"; ctx.lineWidth = 2; ctx.beginPath(); for (let i = -2; i <= 2; i++) { ctx.moveTo(x + i * r * 0.3, y - r * 0.55); ctx.lineTo(x + i * r * 0.25, y - r * 0.2); } ctx.stroke();
      ctx.fillStyle = "#3B2340"; ctx.fillRect(x - r * 0.35, y - 2, 3, 3); ctx.fillRect(x + r * 0.25, y - 2, 3, 3);
    };
    const chili = (x, y) => { ctx.fillStyle = "#FF5A3C"; ctx.beginPath(); ctx.ellipse(x, y, 6, 15, 0.4, 0, 6.29); ctx.fill(); ctx.fillStyle = "#3E8E6A"; ctx.fillRect(x + 2, y - 18, 6, 6); };
    const loop = (now) => {
      const dt = Math.min(32, now - (last || now)); last = now; frame++;
      S.t += dt; S.idle += dt;
      if (S.keys.ArrowLeft) { S.tx -= 0.45 * dt; S.idle = 0; }
      if (S.keys.ArrowRight) { S.tx += 0.45 * dt; S.idle = 0; }
      const demo = S.idle > 2500;
      if (demo) { const tgt = S.items.filter((it) => it.k === "d").sort((a, b) => b.y - a.y)[0]; if (tgt) S.tx = tgt.x; }
      S.tx = Math.max(58, Math.min(362, S.tx));
      S.x += (S.tx - S.x) * 0.18;
      if (frame % 30 === 0) S.items.push({ x: 40 + ((S.t * 7.3) % 340), y: -20, v: 1.6 + (S.score % 9) * 0.08, k: frame % 150 === 0 ? "c" : "d", r: 0 });
      ctx.fillStyle = "#A8D8FF"; ctx.fillRect(0, 0, 420, 320);
      ctx.fillStyle = "#FFD34E"; ctx.beginPath(); ctx.arc(360, 52, 26, 0, 6.29); ctx.fill();
      ctx.fillStyle = "#FFF4E0"; [[60, 60], [210, 34], [300, 92]].forEach(([cx, cy], i) => { const ox = ((S.t / (40 + i * 12)) % 520) - 60; ctx.beginPath(); ctx.arc(cx + ox - 200, cy, 16, 0, 6.29); ctx.arc(cx + ox - 182, cy - 8, 20, 0, 6.29); ctx.arc(cx + ox - 160, cy, 16, 0, 6.29); ctx.fill(); });
      ctx.fillStyle = "#8FD9B6"; ctx.fillRect(0, 290, 420, 30);
      S.items.forEach((it) => { it.y += it.v * dt * 0.06; it.r += 0.03; if (it.k === "d") dumpling(it.x, it.y, 21); else chili(it.x, it.y); });
      const bx = S.x + (S.shake > 0 ? Math.sin(S.t / 20) * 6 : 0); S.shake -= dt;
      S.items = S.items.filter((it) => {
        if (it.y > 248 && it.y < 280 && Math.abs(it.x - S.x) < 44) { if (it.k === "d") { S.score++; } else { S.score = Math.max(0, S.score - 3); S.shake = 400; } return false; }
        return it.y < 340;
      });
      ctx.fillStyle = "#B5793F"; ctx.fillRect(bx - 50, 262, 100, 28); ctx.fillStyle = "#8C5A2B"; ctx.fillRect(bx - 50, 270, 100, 4); ctx.fillRect(bx - 50, 280, 100, 4); ctx.fillStyle = "#D9A066"; ctx.fillRect(bx - 56, 258, 112, 6);
      ctx.fillStyle = "#3B2340"; ctx.font = "16px Fredoka, sans-serif"; ctx.fillText("SCORE " + String(S.score).padStart(3, "0"), 14, 24);
      if (demo && Math.floor(S.t / 600) % 2) { ctx.fillStyle = "#FF5A3C"; ctx.fillText("DEMO, MOVE TO PLAY", 250, 24); }
      if (frame % 10 === 0) setHud({ score: S.score, demo });
      raf = requestAnimationFrame(loop);
    };
    if (reduce) { S.items = [{ x: 140, y: 120, v: 0, k: "d", r: 0 }, { x: 260, y: 180, v: 0, k: "d", r: 0 }]; }
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [reduce]);
  const key = (down) => (e) => { if (e.key === "ArrowLeft" || e.key === "ArrowRight") { e.preventDefault(); st.current.keys[e.key] = down; } };
  const tilt = hud.demo ? 0 : Math.max(-20, Math.min(20, (st.current.tx - st.current.x) * 0.6));
  return (
    <div className="flex flex-col items-center">
      <canvas ref={cv} tabIndex={0} role="img" aria-label={"Dumpling catching mini game. Move the mouse or use the arrow keys. Score " + hud.score} onPointerMove={(e) => { st.current.tx = toLocal(e); st.current.idle = 0; }} onKeyDown={key(true)} onKeyUp={key(false)} onBlur={() => (st.current.keys = {})} className="block cursor-none outline-none focus-visible:ring-4 focus-visible:ring-[#FFD34E]" style={{ width: 420, height: 320, borderRadius: 18, imageRendering: "auto" }} />
