        <div className="flex gap-3">{[K.butter, K.mint].map((c) => <span key={c} className="h-11 w-11 rounded-full" style={{ background: c, boxShadow: "inset -4px -5px 0 rgba(0,0,0,0.2)" }} />)}</div>
      </div>
    </div>
  );
}

