function Lasers() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const tx = useMotionValue(640), sx = useSpring(tx, { stiffness: 40, damping: 12 });
  const [x, setX] = useState(640);
  useMotionValueEvent(sx, "change", (v) => setX(v));
  const user = useRef(false);
  useAnimationFrame((t) => { if (!reduce && !user.current) tx.set(640 + Math.sin(t / 1500) * 420); });
  useEffect(() => {
    const el = ref.current.parentElement;
    const mv = (e) => { const b = el.getBoundingClientRect(); user.current = true; tx.set(((e.clientX - b.left) / b.width) * 1280); };
    const lv = () => (user.current = false);
    el.addEventListener("pointermove", mv); el.addEventListener("pointerleave", lv);
    return () => { el.removeEventListener("pointermove", mv); el.removeEventListener("pointerleave", lv); };
  }, []);
  return (
    <svg ref={ref} viewBox="0 0 1280 720" className="pointer-events-none absolute inset-0 h-full w-full" aria-hidden="true">
      {Array.from({ length: 9 }, (_, i) => <line key={i} x1="640" y1="-10" x2={x + (i - 4) * 120} y2="740" stroke={T.hot} strokeWidth={i === 4 ? 2 : 1} opacity={0.3 + (4 - Math.abs(i - 4)) * 0.14} />)}
      <circle cx="640" cy="0" r="10" fill={T.hot} />
    </svg>
  );
}

function EqWord({ word, offset }) {
