      ))}
    </div>
  );
}

function Scope() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  useEffect(() => {
    const cv = ref.current, ctx = cv.getContext("2d");
    cv.width = 1200; cv.height = 240; let raf, t = 0;
    const draw = () => {
      t += 0.016; ctx.clearRect(0, 0, 1200, 240);
      const kick = Math.exp(-((t % BEAT) / BEAT) * 6);
      ctx.strokeStyle = "#F2F0EB"; ctx.lineWidth = 2.5; ctx.beginPath();
      for (let x = 0; x <= 1200; x += 4) {
        const p = x / 1200;
        const y = 120 + Math.sin(p * 40 + t * 9) * 60 * kick * Math.sin(p * 3.14) + Math.sin(p * 210 + t * 30) * 10 * (0.3 + kick) + Math.sin(p * 9 - t * 2) * 26;
        x ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      }
      ctx.stroke();
      ctx.fillStyle = "#FF3D00"; ctx.fillRect(0, 226, 1200 * kick, 6);
      if (!reduce) raf = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf);
  }, [reduce]);
  return <canvas ref={ref} aria-hidden="true" className="w-full" style={{ height: 120 }} />;
}

