const BONE = "#F1ECE1", GREEN = "#16302B", OX = "#7A2430", INK = "#1E2220", MUTED = "#5E625C";

function ring(a, b, k, phase, n) {
  let d = "";
  for (let i = 0; i <= n; i++) {
    const t = (i / n) * Math.PI * 2;
    const r = a + b * Math.sin(k * t + phase);
    d += (i ? "L" : "M") + (r * Math.cos(t)).toFixed(1) + " " + (r * Math.sin(t)).toFixed(1);
  }
  return d + "Z";
}
function troch(R, r, dd, turns, n) {
  let d = "";
  for (let i = 0; i <= n; i++) {
    const t = (i / n) * Math.PI * 2 * turns;
    const x = (R - r) * Math.cos(t) + dd * Math.cos(((R - r) / r) * t);
    const y = (R - r) * Math.sin(t) - dd * Math.sin(((R - r) / r) * t);
    d += (i ? "L" : "M") + x.toFixed(1) + " " + y.toFixed(1);
  }
  return d;
}
