const DISPLAY = { fontFamily: "'Alegreya', Georgia, serif" };
const BODY = { fontFamily: "'Alegreya Sans', system-ui, sans-serif" };
const OAT = "#EEE6D8", UMBER = "#2E241D", CLAY = "#B5643C", CELADON = "#5E8C78", SAND = "#E0D0B8";

function profile(h, belly, neck, lip) {
  const base = 344, foot = 46;
  const top = base - h;
  const yb = base - h * 0.38, yn = base - h * 0.84;
  const R = [[foot, base], [belly, yb], [neck, yn], [lip, top]];
  let d = "M" + (200 - foot) + " " + base + " L" + (200 + foot) + " " + base;
  d += " C" + (200 + foot + 30) + " " + (base - 4) + " " + (200 + belly) + " " + (yb + h * 0.2) + " " + (200 + belly) + " " + yb;
  d += " C" + (200 + belly) + " " + (yb - h * 0.26) + " " + (200 + neck) + " " + (yn + h * 0.14) + " " + (200 + neck) + " " + yn;
  d += " C" + (200 + neck) + " " + (yn - h * 0.06) + " " + (200 + lip) + " " + (top + 8) + " " + (200 + lip) + " " + top;
  d += " L" + (200 - lip) + " " + top;
  d += " C" + (200 - lip) + " " + (top + 8) + " " + (200 - neck) + " " + (yn - h * 0.06) + " " + (200 - neck) + " " + yn;
  d += " C" + (200 - neck) + " " + (yn + h * 0.14) + " " + (200 - belly) + " " + (yb - h * 0.26) + " " + (200 - belly) + " " + yb;
  d += " C" + (200 - belly) + " " + (yb + h * 0.2) + " " + (200 - foot - 30) + " " + (base - 4) + " " + (200 - foot) + " " + base + " Z";
  return { d, R, top, base };
}
function radiusAt(R, y) {
  for (let i = 0; i < R.length - 1; i++) {
    const a = R[i], b = R[i + 1];
    if (y <= a[1] && y >= b[1]) {
      const t = (a[1] - y) / (a[1] - b[1]);
      const s = t * t * (3 - 2 * t);
      return a[0] + (b[0] - a[0]) * s;
    }
  }
  return R[R.length - 1][0];
}
const rnd = (i, k) => { const v = Math.sin(i * 127.1 + k * 311.7) * 43758.5453; return v - Math.floor(v); };
const SPECKS = Array.from({ length: 170 }, (_, i) => [rnd(i, 1), rnd(i, 2) * Math.PI * 2, 0.6 + rnd(i, 3) * 1.1]);

function Wheel() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const px = useMotionValue(0.5), py = useMotionValue(0.5);
  const sx = useSpring(px, { stiffness: 40, damping: 14 }), sy = useSpring(py, { stiffness: 40, damping: 14 });
  const clock = useMotionValue(0);
  useAnimationFrame((t) => { if (!reduce) clock.set(t / 1000); });
  const shape = useTransform([clock, sx, sy], ([t, x, y]) => {
    const breath = Math.sin(t * 0.55);
    const h = 170 + (1 - y) * 120 + breath * 8;
    const belly = 70 + x * 60 + breath * 5;
    const neck = 36 + (1 - x) * 10 - breath * 3;
    const lip = 44 + x * 18 + breath * 2;
    return profile(h, belly, neck, lip);
  });
  const potD = useTransform(shape, (s) => s.d);
  const glazeD = useTransform([shape, clock], ([s, t]) => {
    const yg = s.base - (s.base - s.top) * 0.46;
    let d = "M0 " + (s.top - 10);
    for (let x = 0; x <= 400; x += 4) {
      const drip = Math.pow(Math.max(0, Math.sin(x * 0.07 + t * 1.1)), 6) * 22 + Math.sin(x * 0.025 - t * 1.1) * 4;
      d += " L" + x + " " + (yg + drip).toFixed(1);
    }
    return d + " L400 " + (s.top - 10) + " Z";
  });
  const speckD = useTransform([shape, clock], ([s, t]) => {
    let d = "";
    for (const [fy, th0, r] of SPECKS) {
      const y = s.base - 6 - fy * (s.base - s.top - 12);
      const th = th0 + t * 1.1;
      if (Math.cos(th) < 0.15) continue;
      const x = 200 + radiusAt(s.R, y) * Math.sin(th) * 0.94;
      d += "M" + (x - r).toFixed(1) + " " + y.toFixed(1) + " a" + r + " " + r + " 0 1 0 " + 2 * r + " 0 a" + r + " " + r + " 0 1 0 " + -2 * r + " 0 ";
    }
    return d;
  });
  const ringsD = useTransform([shape, clock], ([s, t]) => {
    let d = "";
    const n = 7;
    for (let i = 1; i <= n; i++) {
      const y = s.base - ((i + ((t * 0.12) % 1)) / (n + 1)) * (s.base - s.top);
      const r = radiusAt(s.R, y) - 2;
      d += "M" + (200 - r).toFixed(1) + " " + y.toFixed(1) + " Q200 " + (y + 7).toFixed(1) + " " + (200 + r).toFixed(1) + " " + y.toFixed(1) + " ";
    }
    return d;
  });
  const ticks = useTransform(clock, (t) => {
    let d = "";
    for (let i = 0; i < 24; i++) {
      const th = (i / 24) * Math.PI * 2 + t * 2.2;
      if (Math.sin(th) < 0) continue;
      const x = 200 + Math.cos(th) * 128, y = 350 + Math.sin(th) * 22;
      d += "M" + x.toFixed(1) + " " + y.toFixed(1) + " l0 5 ";
    }
    return d;
  });
  const move = (e) => {
    const b = ref.current.getBoundingClientRect();
    px.set(Math.min(1, Math.max(0, (e.clientX - b.left) / b.width)));
    py.set(Math.min(1, Math.max(0, (e.clientY - b.top) / b.height)));
  };
  return (
    <div ref={ref} onPointerMove={move} onPointerLeave={() => { px.set(0.5); py.set(0.5); }} className="relative h-full w-full">
      <svg viewBox="0 0 400 420" className="h-full w-full" role="img" aria-label="A vase turning on the potter's wheel">
        <defs>
          <linearGradient id="ln-body" x1="0" x2="1">
            <stop offset="0" stopColor="#7E3F22" />
            <stop offset="0.38" stopColor="#C97A50" />
            <stop offset="0.55" stopColor={CLAY} />
            <stop offset="1" stopColor="#6A3219" />
          </linearGradient>
          <linearGradient id="ln-glaze" x1="0" x2="1">
            <stop offset="0" stopColor="#4C7464" />
            <stop offset="0.36" stopColor="#A9C9B6" />
            <stop offset="0.6" stopColor="#7FA894" />
            <stop offset="1" stopColor="#3E5F52" />
          </linearGradient>
          <clipPath id="ln-pot"><motion.path d={potD} /></clipPath>
        </defs>
        <ellipse cx="200" cy="372" rx="170" ry="30" fill="#2E241D" opacity="0.12" />
        <path d="M60 350 L60 372 A140 24 0 0 0 340 372 L340 350 Z" fill="#5A4A3E" />
        <ellipse cx="200" cy="350" rx="140" ry="24" fill="#8A7766" />
        <ellipse cx="200" cy="350" rx="128" ry="20" fill="#A39079" />
        <motion.path d={ticks} stroke="#6E5C4C" strokeWidth="2" strokeLinecap="round" />
        <ellipse cx="200" cy="346" rx="66" ry="8" fill="#3E2A1E" opacity="0.35" />
        <motion.path d={potD} fill="url(#ln-body)" />
        <g clipPath="url(#ln-pot)">
          <motion.path d={glazeD} fill="url(#ln-glaze)" />
          <motion.path d={ringsD} fill="none" stroke="#2E241D" strokeOpacity="0.16" strokeWidth="1.4" />
          <motion.path d={speckD} fill="#3A2416" fillOpacity="0.45" />
          <rect x="0" y="0" width="400" height="420" fill="url(#ln-body)" opacity="0.0" />
        </g>
        <motion.path d={potD} fill="none" stroke="#2E241D" strokeOpacity="0.25" strokeWidth="1" />
      </svg>
    </div>
  );
}

