const CURVE = [[0, 20], [2, 100], [5, 110], [9, 573], [12, 900], [15, 1100], [17.5, 1240], [18, 1240], [21, 700], [26, 300], [32, 60]];
const NOTES = [[3.5, 105, "Water smoke"], [9, 573, "Quartz turns"], [15, 1100, "Glaze melts"], [17.75, 1240, "Peak, held 20 min"], [26, 300, "Doors stay shut"]];
const cx = (h) => 60 + (h / 32) * 1060, cy = (t) => 330 - (t / 1300) * 280;

function Kiln() {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start 0.85", "end 0.6"] });
  const draw = useTransform(scrollYProgress, [0, 1], [0, 1]);
  const heat = useTransform(scrollYProgress, [0, 0.55, 1], ["#2E241D", "#5A2614", "#2E241D"]);
  let d = "M" + cx(CURVE[0][0]) + " " + cy(CURVE[0][1]);
  for (let i = 1; i < CURVE.length; i++) {
    const p = CURVE[i - 1], q = CURVE[i];
    const mx = (cx(p[0]) + cx(q[0])) / 2;
    d += " C" + mx + " " + cy(p[1]) + " " + mx + " " + cy(q[1]) + " " + cx(q[0]) + " " + cy(q[1]);
  }
  return (
    <motion.section ref={ref} style={{ background: heat }} className="relative px-16 py-24 text-[#EEE6D8]">
      <div className="flex items-end justify-between">
        <h2 className="max-w-[40rem] text-[3.4rem] leading-[1.02]" style={{ ...DISPLAY, fontWeight: 500 }}>Thirty-two hours in the kiln, <em className="italic text-[#E7A07A]" style={{ fontWeight: 400 }}>and we do not open early.</em></h2>
        <p className="max-w-[18rem] text-[16px] leading-[1.55] text-[#EEE6D8]/70" style={BODY}>The glaze firing for every piece in the shop, logged by the thermocouple on the back wall.</p>
      </div>
      <svg viewBox="0 0 1160 380" className="mt-12 w-full overflow-visible" role="img" aria-label="Firing curve: up to 1,240°C at hour 17, then a slow cool">
        {[0, 400, 800, 1200].map((t) => (
          <g key={t}><path d={"M60 " + cy(t) + " H1120"} stroke="#EEE6D8" strokeOpacity="0.12" /><text x="50" y={cy(t) + 4} textAnchor="end" fill="#EEE6D8" fillOpacity="0.5" style={{ ...BODY, fontSize: 12 }}>{t}°</text></g>
        ))}
        {[0, 8, 16, 24, 32].map((h) => <text key={h} x={cx(h)} y="364" textAnchor="middle" fill="#EEE6D8" fillOpacity="0.5" style={{ ...BODY, fontSize: 12 }}>{h}h</text>)}
        <path d={d} fill="none" stroke="#EEE6D8" strokeOpacity="0.12" strokeWidth="2" />
        <motion.path d={d} fill="none" stroke="#E7A07A" strokeWidth="3" strokeLinecap="round" style={{ pathLength: draw }} />
        {NOTES.map((n, i) => (
          <Note key={n[2]} n={n} progress={draw} at={n[0] / 32} />
        ))}
      </svg>
    </motion.section>
  );
}
