  const leafScale = useTransform(p, [0, 0.25, 0.85, 1], [0.15, 1, 1, 0.9]);
  const leafColor = useTransform(p, [0, 0.3, 0.62, 0.78, 0.92], ["#9DB060", "#5F7A3A", "#5F7A3A", "#C9963E", "#A8492E"]);
  const leafFall = useTransform(p, [0.86, 1], [0, 90]);
  const leafFade = useTransform(p, [0.88, 1], [1, 0]);
  const grapeScale = useTransform(p, [0.28, 0.5], [0, 1]);
  const grapeColor = useTransform(p, [0.5, 0.66], ["#A9B86A", "#4A1F3A"]);
  const grapeGone = useTransform(p, [0.7, 0.76], [1, 0]);
  const bg = useTransform(p, [0, 0.4, 0.7, 1], ["#E7E6D3", "#EFE6C8", "#EBD7B9", "#E2DCD8"]);
