  return (
    <motion.section ref={ref} style={{ background: bg }} className="relative overflow-hidden px-16 pb-20 pt-24">
      <div className="flex items-end justify-between">
        <h2 className="text-[4.2rem] leading-[0.95] text-[#2A1A24]" style={{ ...SERIF, fontWeight: 400 }}>A year on the hill</h2>
        <p className="text-[4.2rem] italic leading-[0.95] text-[#8C2F39]" style={{ ...SERIF, fontWeight: 300 }}><motion.span>{month}</motion.span></p>
      </div>
      <svg viewBox="0 0 1160 420" className="mt-10 w-full" role="img" aria-label="One vine through the seasons: leaves, grapes, harvest and bare wood">
        <motion.circle cx="1040" cy={sun} r="34" fill={GOLD} opacity="0.45" />
        <path d="M0 360 H1160" stroke="#6E5A4A" strokeWidth="2" />
        <path d="M60 170 H1110" stroke="#8A7A6A" strokeWidth="1.2" />
        <path d="M60 250 H1110" stroke="#8A7A6A" strokeWidth="1.2" />
        {[60, 400, 760, 1110].map((x) => <rect key={x} x={x - 3} y="150" width="6" height="210" fill="#7A5A44" />)}
        <path d="M580 360 C576 320 590 290 578 258 C566 230 600 250 640 250 L1100 252 M578 258 C540 250 420 252 100 250" fill="none" stroke="#4A3226" strokeWidth="9" strokeLinecap="round" />
        {SHOOTS.map(([x, dir], i) => (
          <g key={i}>
            <path d={"M" + x + " 250 C" + (x + dir * 10) + " 210 " + (x - dir * 14) + " 190 " + (x + dir * 6) + " 150"} fill="none" stroke="#5A4630" strokeWidth="3" />
            {[[x + dir * 10, 214, 0], [x - dir * 12, 186, 1], [x + dir * 8, 154, 2]].map(([lx, ly, j]) => (
              <g key={j} transform={"translate(" + lx + " " + (ly - 18) + ")"}>
                <motion.g style={{ y: leafFall, opacity: leafFade }}>
                  <motion.g style={{ scale: leafScale, originX: 0.5, originY: 0 }} animate={reduce ? {} : { rotate: [dir * 10 - 6, dir * 10 + 6] }} transition={{ duration: 2.6 + j * 0.7 + i * 0.2, repeat: Infinity, repeatType: "mirror", ease: "easeInOut" }}>
                    <motion.path d={LEAF} style={{ fill: leafColor }} />
                    <path d={VEINS} stroke="#F3EBD2" strokeOpacity="0.35" strokeWidth="1.2" fill="none" />
                  </motion.g>
                </motion.g>
              </g>
            ))}
            <motion.g style={{ scale: grapeScale, opacity: grapeGone, originX: 0.5, originY: 0 }}>
              {[[0, 0], [-8, 8], [8, 8], [0, 16], [-6, 24], [6, 24], [0, 32], [-12, 0], [12, 0]].map(([gx, gy], g) => (
                <motion.circle key={g} cx={x + dir * 4 + gx} cy={268 + gy} r="7" style={{ fill: grapeColor }} />
