        {STAGES.map((s, i) => <Stage key={s[0]} s={s} p={p} at={i / 3} />)}
      </div>
    </motion.section>
  );
}
function Stage({ s, p, at }) {
  const o = useTransform(p, [at - 0.25, at, at + 0.25], [0.35, 1, 0.35]);
  return (
    <motion.div style={{ opacity: o }}>
