const F = { fontFamily: "'Bricolage Grotesque', system-ui, sans-serif" };
const PLASTER = "#F3EDE4", TEAL = "#1F3B3A", APRICOT = "#E98B5F", SAGE = "#C9D6C3", BLUSH = "#EBCFC0";
const rad = (d) => (d * Math.PI) / 180;
const ease = (p) => (1 - Math.cos(p * Math.PI * 2)) / 2;

const MOVES = {
  reach: { name: "Shoulder reach", joint: "shoulder", rest: 15, note: "Frozen shoulder, rotator cuff, desk neck" },
  hinge: { name: "Hip hinge", joint: "hip", rest: 0, note: "Lower back pain, hamstrings, lifting" },
  squat: { name: "Deep squat", joint: "knee", rest: 0, note: "Knees, ankles, getting up off the floor" },
};

function pose(kind, p) {
  const e = ease(p);
  let torso = 0, thigh = 0, knee = 0, armN = 15, armF = 10, elbow = 8;
  if (kind === "reach") { armN = 15 + e * 155; armF = 10 + e * 120; torso = -e * 6; elbow = 8 - e * 6; }
  if (kind === "hinge") { torso = e * 72; thigh = e * 22; knee = e * 30; armN = e * 70 + 4; armF = e * 70; }
  if (kind === "squat") { thigh = e * 96; knee = e * 116; torso = e * 38; armN = e * 84 + 6; armF = e * 80; elbow = 4; }
  const hip = [0, 0];
  const kneeN = [hip[0] + Math.sin(rad(thigh)) * 108, hip[1] + Math.cos(rad(thigh)) * 108];
  const ankleN = [kneeN[0] + Math.sin(rad(thigh - knee)) * 112, kneeN[1] + Math.cos(rad(thigh - knee)) * 112];
  const sh = [hip[0] + Math.sin(rad(torso)) * 150, hip[1] - Math.cos(rad(torso)) * 150];
  const head = [sh[0] + Math.sin(rad(torso * 1.05)) * 52, sh[1] - Math.cos(rad(torso * 1.05)) * 52];
  const arm = (a) => {
    const el = [sh[0] + Math.sin(rad(a)) * 92, sh[1] + Math.cos(rad(a)) * 92];
    const wr = [el[0] + Math.sin(rad(a + elbow)) * 86, el[1] + Math.cos(rad(a + elbow)) * 86];
    return [el, wr];
  };
  const aN0 = arm(armN), aF0 = arm(armF);
  const dx = -ankleN[0] - 10, dy = -ankleN[1];
  const m = (q) => [q[0] + dx, q[1] + dy];
  return { hip: m(hip), kneeN: m(kneeN), ankleN: m(ankleN), sh: m(sh), head: m(head), aN: aN0.map(m), aF: aF0.map(m), torso, thigh, knee, armN, angle: kind === "reach" ? armN : kind === "hinge" ? torso : knee };
}
const seg = (pts) => pts.map((q, i) => (i ? "L" : "M") + q[0].toFixed(1) + " " + q[1].toFixed(1)).join(" ");

function Figure({ kind }) {
  const reduce = useReducedMotion();
  const t = useMotionValue(0.25);
  const start = useRef(null);
  useEffect(() => { start.current = null; }, [kind]);
  useAnimationFrame((ms) => {
    if (reduce) { t.set(0.32); return; }
    if (start.current === null) start.current = ms;
    t.set(((ms - start.current) / 6400 + 0.12) % 1);
  });
  const P = useTransform(t, (v) => pose(kind, v));
  const torsoD = useTransform(P, (q) => seg([q.hip, q.sh]));
  const neckD = useTransform(P, (q) => seg([q.sh, [q.sh[0] + (q.head[0] - q.sh[0]) * 0.45, q.sh[1] + (q.head[1] - q.sh[1]) * 0.45]]));
  const legN = useTransform(P, (q) => seg([q.hip, q.kneeN, q.ankleN, [q.ankleN[0] + 34, q.ankleN[1]]]));
  const legF = useTransform(P, (q) => seg([[q.hip[0] - 14, q.hip[1]], [q.kneeN[0] - 16, q.kneeN[1]], [q.ankleN[0] - 18, q.ankleN[1]], [q.ankleN[0] + 14, q.ankleN[1]]]));
  const armN = useTransform(P, (q) => seg([q.sh, q.aN[0], q.aN[1]]));
  const armF = useTransform(P, (q) => seg([[q.sh[0] - 10, q.sh[1] + 4], [q.aF[0][0] - 12, q.aF[0][1]], [q.aF[1][0] - 12, q.aF[1][1]]]));
  const hx = useTransform(P, (q) => q.head[0]), hy = useTransform(P, (q) => q.head[1]);
  const arc = useTransform(P, (q) => {
    const m = MOVES[kind];
    const c = m.joint === "shoulder" ? q.sh : m.joint === "hip" ? q.hip : q.kneeN;
    const r = 70;
    const a0 = m.joint === "shoulder" ? q.armN : m.joint === "hip" ? 0 : q.thigh;
    const a1 = m.joint === "shoulder" ? m.rest : m.joint === "hip" ? q.torso : q.thigh - q.knee;
    const dirs = m.joint === "hip" ? [rad(180), rad(180 + a1)] : [rad(a1), rad(a0)];
    const from = m.joint === "hip" ? [c[0], c[1] - r] : [c[0] + Math.sin(dirs[0]) * r, c[1] + Math.cos(dirs[0]) * r];
    const to = m.joint === "hip" ? [c[0] + Math.sin(rad(a1)) * r, c[1] - Math.cos(rad(a1)) * r] : [c[0] + Math.sin(dirs[1]) * r, c[1] + Math.cos(dirs[1]) * r];
    const span = Math.abs(q.angle - (m.joint === "shoulder" ? m.rest : 0));
    const sweep = m.joint === "shoulder" ? 0 : m.joint === "hip" ? 1 : 1;
    return "M" + from[0].toFixed(1) + " " + from[1].toFixed(1) + " A" + r + " " + r + " 0 " + (span > 180 ? 1 : 0) + " " + sweep + " " + to[0].toFixed(1) + " " + to[1].toFixed(1);
  });
  const deg = useTransform(P, (q) => Math.round(q.angle) + "°");
  const lx = useTransform(P, (q) => (MOVES[kind].joint === "shoulder" ? q.sh : MOVES[kind].joint === "hip" ? q.hip : q.kneeN)[0] + (kind === "hinge" ? -120 : 84));
  const ly = useTransform(P, (q) => (MOVES[kind].joint === "shoulder" ? q.sh : MOVES[kind].joint === "hip" ? q.hip : q.kneeN)[1] + (kind === "reach" ? -40 : kind === "hinge" ? -20 : 10));
  const sw = 30;
  return (
    <svg viewBox="-310 -640 620 680" className="h-full w-full" role="img" aria-label={"Animated figure doing a " + MOVES[kind].name.toLowerCase()}>
      <ellipse cx="0" cy="14" rx="170" ry="14" fill={TEAL} opacity="0.1" />
      <path d="M-290 6 H290" stroke={TEAL} strokeOpacity="0.25" strokeWidth="2" />
      <motion.path d={armF} fill="none" stroke="#7FA39A" strokeWidth={sw - 4} strokeLinecap="round" strokeLinejoin="round" />
      <motion.path d={legF} fill="none" stroke="#7FA39A" strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" />
      <motion.path d={torsoD} fill="none" stroke={TEAL} strokeWidth={sw + 22} strokeLinecap="round" />
      <motion.path d={neckD} fill="none" stroke={TEAL} strokeWidth={sw - 8} strokeLinecap="round" />
      <motion.circle cx={hx} cy={hy} r="30" fill={APRICOT} />
      <motion.path d={legN} fill="none" stroke={TEAL} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" />
      <motion.path d={armN} fill="none" stroke={TEAL} strokeWidth={sw - 4} strokeLinecap="round" strokeLinejoin="round" />
      <motion.path d={arc} fill="none" stroke={APRICOT} strokeWidth="3" strokeDasharray="2 7" strokeLinecap="round" />
      <motion.text x={lx} y={ly} fill={TEAL} style={{ ...F, fontSize: 30, fontWeight: 600, fontVariantNumeric: "tabular-nums" }}>{deg}</motion.text>
    </svg>
  );
}

