const HOUR = [["Talk", 15, "What happened, what you need to do again, what worries you."], ["Assess", 20, "Strength, range and the movement that hurts, measured."], ["Treat", 15, "Hands-on work and the first exercise, done together."], ["Plan", 10, "Three exercises on your phone and a date to check them."]];

function FirstHour() {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start 0.75", "end 0.55"] });
  const fill = useSpring(scrollYProgress, { stiffness: 70, damping: 22 });
  const minutes = useTransform(fill, (v) => Math.round(Math.min(1, Math.max(0, v)) * 60) + " min");
  let acc = 0;
  return (
    <section ref={ref} className="px-14 py-24">
      <div className="flex items-end justify-between">
        <h2 className="text-[3.6rem] leading-[0.98] tracking-[-0.03em] text-[#1F3B3A]" style={{ ...F, fontWeight: 600 }}>Your first hour</h2>
        <motion.p className="text-[3.6rem] leading-none tracking-[-0.03em] text-[#E98B5F]" style={{ ...F, fontWeight: 300, fontVariantNumeric: "tabular-nums" }}>{minutes}</motion.p>
      </div>
      <div className="relative mt-12 h-4 overflow-hidden rounded-full bg-[#E4DCCF]">
        <motion.div className="absolute inset-0 origin-left rounded-full bg-[#1F3B3A]" style={{ scaleX: fill }} />
      </div>
      <div className="mt-8 flex gap-4">
        {HOUR.map((h) => {
          const at = acc / 60;
          acc += h[1];
          return <Step key={h[0]} h={h} fill={fill} at={at} />;
        })}
      </div>
    </section>
  );
}
function Step({ h, fill, at }) {
  const o = useTransform(fill, [at, at + 0.06], [0.35, 1]);
  return (
    <motion.div style={{ opacity: o, flexGrow: h[1], flexBasis: 0 }} className="border-l-2 border-[#1F3B3A] pl-4">
      <p className="text-[14px] tabular-nums text-[#4A5E5B]">{h[1]} min</p>
      <p className="mt-1 text-[1.6rem] font-semibold tracking-[-0.02em] text-[#1F3B3A]">{h[0]}</p>
      <p className="mt-2 max-w-[17rem] text-[15px] leading-[1.55] text-[#4A5E5B]">{h[2]}</p>
    </motion.div>
  );
}

